{
  "items": [
    {
      "name": "Polynomial.hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → ℕ → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.hasseDeriv_eq_zero_of_lt_natDegree",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ), p.natDegree < n → (Polynomial.hasseDeriv n) p = 0"
    },
    {
      "name": "Polynomial.degree_derivative_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, p ≠ 0 → (Polynomial.derivative p).degree < p.degree"
    },
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "MvPolynomial.weightedTotalDegree'_eq_bot_iff",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M]\n  [inst_2 : SemilatticeSup M] (w : σ → M) (p : MvPolynomial σ R), MvPolynomial.weightedTotalDegree' w p = ⊥ ↔ p = 0"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "Polynomial.hasseDeriv_C",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (r : R), 0 < k → (Polynomial.hasseDeriv k) (Polynomial.C r) = 0"
    },
    {
      "name": "Polynomial.hasseDeriv_one",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R], Polynomial.hasseDeriv 1 = Polynomial.derivative"
    }
  ]
}
